    11	export const isRuleDefType = (type?: unknown): type is InternalRuleType => !!type && Object.values(InternalRuleType).includes(type as InternalRuleType);
    12	export const isRuleDef = (rule?: unknown): rule is InternalRuleDef => !!rule && typeof rule === 'object' && 'type' in rule && isRuleDefType(rule.type);
    13	export const isRuleDefAlt = (rule?: InternalRuleDef): rule is InternalRuleDefReference => rule !== undefined && rule.type === InternalRuleType.ALT;
    14	export const isRuleDefRef = (rule?: InternalRuleDef): rule is InternalRuleDefReference => rule !== undefined && rule.type === InternalRuleType.RULE_REF;
    15	export const isRuleDefEnd = (rule?: InternalRuleDef): rule is InternalRuleDefEnd => rule !== undefined && rule.type === InternalRuleType.END;
